80	aclError aclskOptimize(aclmdlRI model, aclskOptions *options) {
81	  SkModelContext modelContext(model);
82	
83	  // Initialize logger first (controlled by environment variable ASCEND_OP_COMPILE_SAVE_KERNEL_META)
84	  InitSkLogger(GetCurrentModelLabel());
85	  // Init device socname, corenum, TICK_US_MULTIPLIER
86	  InitSkRuntimeConfig();
87	
88	  std::string metaDir;
89	  aclError ret = PrepareGraphDumpEnv(metaDir);
90	  if (ret != ACL_SUCCESS) {
91	    return ret;
92	  }
93	
94	  SK_LOGI("Start dump tasks by use rts api to JSON...");
95	  ret = DumpMdlJson(model, metaDir, "sk_mdl_origin");
96	  if (ret != ACL_SUCCESS) {
97	    return ret;
98	  }
99	  SK_LOGI("End dump tasks by use rts api to JSON...");
100	  CurrentModelGuard modelGuard(model);
101	  ret = SkResourceManager::CallbackRegister(model);
102	  if (ret != ACL_SUCCESS) {
103	    return ret;
104	  }
105	  ret = aclrtSetExceptionInfoCallback(SuperKernelExceptionCallBackFunc);
106	  if (ret != ACL_SUCCESS) {
107	    SK_LOGE("Failed to set exception callback.");
108	    return ACL_ERROR_FAILURE;
109	  }
110	  if (Adx::AdumpRegExceptionDumpCallback) {
111	    SK_LOGI("Register exception dump callback.");
112	    ret = Adx::AdumpRegExceptionDumpCallback(ExceptionDumpInfoCallBack);
113	    if (ret != ACL_SUCCESS) {
114	      SK_LOGE("Failed to register exception dump callback.");
115	      return ACL_ERROR_FAILURE;
116	    }
117	    SK_LOGI("Register exception dump callback success.");
118	  }
119	  SK_LOGI("Begin aclskOptimize");
120	  SK_LOGI("Start parse sk options...");
121	  SuperKernelOptionsManager opts;
122	  opts.ParseOptions(options);
123	  SK_LOGI("End parse sk options");
124	
125	  SK_LOGI("Start init sk graph...");
126	  SuperKernelGraph graph(model, opts);
127	  if (!graph.InitSKGraph()) {
128	    return ACL_ERROR_FAILURE;
129	  }
130	
131	  // Dump the initialized graph directly before optimization.
132	  SK_LOGI("Start dump raw tasks from graph to JSON...");
133	  if (!DumpGraphJson(graph, opts, metaDir, "sk_graph_origin")) {
134	    return ACL_ERROR_FAILURE;
135	  }
136	
137	  ret = LockDetector::GetDeviceCores();
138	  if (ret != ACL_SUCCESS) {
139	    return ret;
140	  }
141	  SK_LOGI("End init sk graph");
142	
143	  SK_LOGI("Start init sk time profiling event recorder...");
144	  SkEventRecorder::Instance().Init();  // Initialize event recorder (if ASCEND_PROF_SK_ON=1 environment variable is set)
145	  SK_LOGI("End init sk time profiling event recorder");
146	
147	  SK_LOGI("Start optimize sk graph...");
148	  SuperKernelOptimizer optimizer(opts);
149	  if (!optimizer.Process(graph)) {
150	    SK_LOGE("aclskOptimize failed: optimize sk graph failed");
151	    return ACL_ERROR_FAILURE;
152	  }
153	  SK_LOGI("End optimize sk graph");
154	
155	  SK_LOGI("Start update graph...");
156	  ret = graph.Update();
157	  if (ret != ACL_SUCCESS) {
158	    SK_LOGE("Failed to update graph, ret=%d", ret);
159	    return ret;
160	  }
161	  SK_LOGI("End update graph");
162	
163	  SK_LOGI("Start dump raw tasks after update from modelRI to JSON...");
164	  const auto &scopeInfos = optimizer.GetScopeInfos();
165	  if (!DumpGraphJson(model, opts, metaDir, "sk_graph_updated", &scopeInfos)) {
166	    return ACL_ERROR_FAILURE;
167	  }
168	  SK_LOGI("End dump raw tasks after update from modelRI to JSON...");
169	
170	  SK_LOGI("Start dump kernel binaries...");
171	  if (sk::logger::FileLogger::Instance().IsEnabled()) {
172	    std::string binPath = CreateSkMetaDirectory(graph.GetModelLabel());
173	    if (!DumpKernelBinaries(graph, binPath)) {
174	      SK_LOGE("Failed to dump kernel binaries: %s/bin_files", binPath.c_str());
175	      return ACL_ERROR_FAILURE;
176	    }
177	  }
178	  SK_LOGI("End dump kernel binaries");
179	
180	  SK_LOGI("Start dump tasks after update by use rts api to JSON...");
181	  ret = DumpMdlJson(model, metaDir, "sk_mdl_updated");
182	  if (ret != ACL_SUCCESS) {
183	    return ret;
184	  }
185	  SK_LOGI("End dump tasks after update by use rts api to JSON");
186	  return ACL_SUCCESS;
187	}
