22	def get_file_content(file):
23	    data = []
24	    with open(file, 'rb') as fd:
25	        buf = fd.read()
26	        start = 0
27	        while start + 8 <= len(buf):
28	            value = int.from_bytes(buf[start:start + 8], byteorder='little')
29	            data.append(f'0x{value:016x}')
30	            start += 8
31	    return data
32	
