34	def gen_buffer_code(bin_file, symbol):
35	    file_size = os.path.getsize(bin_file)
36	    if file_size % 8 != 0:
37	        raise ValueError(f"Binary file {bin_file} (size: {file_size}) must be 8-byte aligned.")
38	    data = get_file_content(bin_file)
39	    formatted_data = [
40	        "    " + ", ".join(data[i:i + 8]) 
41	        for i in range(0, len(data), 8)
42	    ]
43	    data_lines = ",\n".join(formatted_data)
44	    return f'''static const uint64_t {symbol}[{len(data)}] __attribute__ ((section (".sk.kernel"))) = {{
45	{data_lines}
46	}};
47	''', len(data)
