50	def gen_code(bin_files, src):
51	    buffer_defs = []
52	    bin_entries = []
53	    for arch, bin_file in bin_files:
54	        symbol = "__aicore_file_buf_" + arch.replace("-", "_")
55	        buffer_code, data_len = gen_buffer_code(bin_file, symbol)
56	        buffer_defs.append(buffer_code)
57	        bin_entries.append(f'    {{"{arch}", {symbol}, sizeof({symbol})}}')
58	    bin_entry_lines = ",\n".join(bin_entries)
59	    handle_init = ", ".join(["nullptr"] * len(bin_files))
60	    code = f'''#include <acl/acl.h>
