72	static aclrtBinHandle AscendLoadBinaryFromBuffer(const uint64_t *aicoreFileBuf, size_t fileSize)
73	{{
74	    constexpr uint32_t optLen = 2;
75	    aclrtBinaryLoadOption opList[optLen] = {{
76	        {{ACL_RT_BINARY_LOAD_OPT_LAZY_MAGIC, {{ACL_RT_BINARY_MAGIC_ELF_AICORE}}}},
77	        {{ACL_RT_BINARY_LOAD_OPT_LAZY_LOAD, {{/* isLazyLoad = */1}}}}
78	    }};
79	    aclrtBinaryLoadOptions opts = {{opList, optLen}};
80	    
81	    aclrtBinHandle bhdl = nullptr;
82	    int32_t ret = aclrtBinaryLoadFromData((const char *)aicoreFileBuf, fileSize, &opts, &bhdl);
83	    if (ret != 0) {{
84	        SK_LOGE("aclrtBinaryLoadFromData error, please check log!");
85	    }}
86	    return bhdl;
87	}}
88	
89	struct SkEntryBinary {{
90	    const char *arch;
91	    const uint64_t *data;
92	    size_t size;
93	}};
94	
95	{os.linesep.join(buffer_defs)}
96	
97	static const SkEntryBinary g_sk_entry_bins[] = {{
98	{bin_entry_lines}
99	}};
