101	static const char *GetSkEntryArch()
102	{{
103	    const char *socName = aclrtGetSocName();
104	    if (socName != nullptr && strstr(socName, "Ascend950") != nullptr) {{
105	        return "dav-3510";
106	    }}
107	    return "dav-2201";
108	}}
