110	static size_t GetSkEntryBinIndex()
111	{{
112	    const char *targetArch = GetSkEntryArch();
113	    constexpr size_t binCount = sizeof(g_sk_entry_bins) / sizeof(g_sk_entry_bins[0]);
114	    for (size_t i = 0; i < binCount; ++i) {{
115	        if (strcmp(g_sk_entry_bins[i].arch, targetArch) == 0) {{
116	            return i;
117	        }}
118	    }}
119	    SK_LOGW("No sk_entry binary for arch %s, fallback to %s", targetArch, g_sk_entry_bins[0].arch);
120	    return 0;
121	}}
