124	{{
125	    static thread_local aclrtBinHandle __sk_bin_handles__[{len(bin_files)}] = {{{handle_init}}};
126	    size_t binIndex = GetSkEntryBinIndex();
127	    if (binIndex >= sizeof(g_sk_entry_bins) / sizeof(g_sk_entry_bins[0])) {{
128	        binIndex = 0;
129	    }}
